mapper.select:
SELECT COUNT(*)
  FROM wb_skill
 WHERE project_id = #{projectId}
   AND created_by = #{createdBy}

mapper.delete:
DELETE v
  FROM wb_skill_version v
  JOIN wb_skill s ON s.id = v.skill_id
 WHERE s.project_id = #{projectId}
   AND s.created_by = #{createdBy}

DELETE FROM wb_skill
 WHERE project_id = #{projectId}
   AND created_by = #{createdBy}

mapper.select:
SELECT id, project_id, name, description, current_version_id, created_by, deleted, created_at, updated_at
  FROM wb_skill
 WHERE project_id = #{projectId}
   AND name = #{name}
   AND deleted = 0
 LIMIT 1

mapper.update:
UPDATE wb_skill
   SET current_version_id = #{currentVersionId},
       updated_at = #{updatedAt}
 WHERE id = #{id}

UPDATE wb_skill
   SET deleted = 1,
       updated_at = #{updatedAt}
 WHERE id = #{id}
   AND project_id = #{projectId}
   AND deleted = 0

